param([string]$InputUsd='', [string]$Library='', [string]$OutputDirectory='', [string]$OpenUsdRoot='')
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Local-Paths.ps1')
$OpenUsdRoot=Get-HdUELocalPath -Key openusd_root -Value $OpenUsdRoot
$TaskRoot=Split-Path -Parent $PSScriptRoot
if (-not $InputUsd) {$InputUsd=Join-Path $TaskRoot 'samples\materialx\normal_udim_showcase\normal_udim.usda'}
if (-not $Library) {throw 'Specify the library.json generated by Import-UsdMaterialX.ps1.'}
$Run=if ($OutputDirectory) {[IO.Path]::GetFullPath($OutputDirectory)} else {Join-Path $TaskRoot ('out\texture-check\'+(Get-Date -Format 'yyyyMMdd-HHmmss-fff'))}
if (Test-Path -LiteralPath $Run) {throw 'Choose fresh texture evidence.'}
New-Item -ItemType Directory -Force -Path (Split-Path -Parent $Run) | Out-Null
& (Join-Path $PSScriptRoot 'Launch-Usdview.ps1') -InputUsd $InputUsd -MaterialXLibrary $Library -OpenUsdRoot $OpenUsdRoot -CameraPath /Camera -TestOutput $Run -UsdviewArguments @('--defaultsettings','--hdue-texture-check') *> ($Run+'.log')
$Result=Get-Content -Raw (Join-Path $Run 'verified.json') | ConvertFrom-Json
$Log=[IO.File]::ReadAllText($Run+'.log').Replace([string][char]0,'')
if (-not $Result.passed -or -not $Result.normal_and_udim_verified -or $Result.frames.Count -ne 21 -or $Result.normal_comparisons.Count -ne 8 -or $Result.udim_checks.Count -ne 16 -or $Result.udim_normal_checks.Count -ne 6 -or $Result.runtime_state -ne 4 -or $Result.ue_initializations -ne 1 -or $Log -match '(?m)^hdUE:|Traceback|Runtime Error:|Coding Error:|Fatal error') {throw "Incomplete texture verification: $Run"}
Write-Output "Verified normalmap/UDIM: $Run"
